"""Private local object adapter. Keys are generated by the backend, never by a client."""

import hashlib
import os
import tempfile
from pathlib import Path

from backend.config import settings


class LocalFiles:
    def __init__(self, root: Path) -> None:
        self.root = root.resolve()

    def path(self, key: str) -> Path:
        path = (self.root / key).resolve()
        if not path.is_relative_to(self.root):
            raise ValueError("Invalid storage key")
        return path

    def put(self, key: str, content: bytes) -> None:
        path = self.path(key)
        path.parent.mkdir(parents=True, exist_ok=True)
        fd, temporary = tempfile.mkstemp(dir=path.parent, prefix=".upload-")
        try:
            with os.fdopen(fd, "wb") as file:
                file.write(content)
                file.flush()
                os.fsync(file.fileno())
            try:
                os.link(temporary, path)
            except FileExistsError:
                if path.read_bytes() != content:
                    raise OSError("Stored source bytes do not match the upload.") from None
        finally:
            Path(temporary).unlink(missing_ok=True)

    def read(self, key: str, checksum: str) -> bytes:
        content = self.path(key).read_bytes()
        if hashlib.sha256(content).hexdigest() != checksum:
            raise OSError("Stored source checksum mismatch.")
        return content


def files() -> LocalFiles:
    return LocalFiles(settings().storage_dir)
